import boto3
import json

def extract_key_values(document_path: str) -> dict[str, str]:
    """
    Extracts key-value pairs from a form-like document using AWS Textract.

    :param document_path: Path to the image or PDF file.
    :return: Dictionary of extracted key-value pairs.
    """
    with open(document_path, 'rb') as file:
        image_bytes = file.read()

    textract = boto3.client('textract', region_name='us-east-1')

    response = textract.analyze_document(
        Document={'Bytes': image_bytes},
        FeatureTypes=['FORMS']
    )

    blocks = response['Blocks']

    # Map block IDs to blocks
    block_id_info_map = {block['Id']: block for block in blocks}

    # Extract KEY_VALUE_SET blocks
    key_map = {}
    value_map = {}
    for block_id, block in block_id_info_map.items():
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'KEY' in [rel['Type'] for rel in block['Relationships']]:
                key_map[block_id] = block
            else:
                value_map[block_id] = block

    # Link keys to values
    key_values = {}
    for key_block_id, key_block in key_map.items():
        value_id = None
        for relationship in key_block['Relationships']:
            if relationship['Type'] == 'VALUE':
                value_id = relationship['Ids'][0]
                break
        if value_id and value_id in value_map:
            key_text = key_block['Text']
            value_text = value_map[value_id]['Text']
            key_values[key_text] = value_text

    return key_values
